Rule.Source:


long DEFAULT_SLEEP = 1000L * 60L; // 1 minute
String SLEEP_ARG = "sleepTime";

long sleepTimeActual = DEFAULT_SLEEP;

for (String argName : global.namespace.getVariableNames()) {
    if ("config".equals(argName)) {
        try {
            sleepTimeActual = Long.valueOf(config.get(SLEEP_ARG));
        } catch (Throwable t) {
            log.debug(t);
        }
    }
}

log.warn("Sleeping for: " + sleepTimeActual);
Thread.sleep(sleepTimeActual);
log.warn("Wakey, wakey! Hands off snakey!");
